draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bell pepper
  ctx.fillStyle = '#ff9900'; // orange
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // leaves
  ctx.fillStyle = '#33cc33'; // green
  ctx.beginPath();
  ctx.arc(W/2 - 30, H/2 - 70, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 - 70, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // vitamin c text
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Vitamin C', W/2, H/2 + 80);

  // colorful circles
  ctx.fillStyle = '#ff66cc'; // pink
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2 - 20, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = '#cccc33'; // yellow
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 20, 10 + 5 * Math.cos(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = '#6699ff'; // blue
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2 - 20, 10 + 5 * Math.sin(t + Math.PI/2), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
